ALTER TABLE wb.release_batch ADD COLUMN relation_revision bigint NOT NULL DEFAULT 1 CHECK(relation_revision>0);
CREATE TABLE wb.requirement(project_id text NOT NULL REFERENCES wb.project, requirement_id text NOT NULL CHECK(btrim(requirement_id)<>''), source_system text NOT NULL CHECK(btrim(source_system)<>''), source_namespace text NOT NULL CHECK(btrim(source_namespace)<>''), source_object_id text NOT NULL CHECK(btrim(source_object_id)<>''), source_revision text NOT NULL CHECK(btrim(source_revision)<>''), source_ref text NOT NULL CHECK(btrim(source_ref)<>''), PRIMARY KEY(project_id,requirement_id), UNIQUE(project_id,source_system,source_namespace,source_object_id));
CREATE TABLE wb.batch_requirement(project_id text NOT NULL, batch_id text NOT NULL, requirement_id text NOT NULL, PRIMARY KEY(project_id,batch_id,requirement_id), FOREIGN KEY(project_id,batch_id) REFERENCES wb.release_batch, FOREIGN KEY(project_id,requirement_id) REFERENCES wb.requirement);
CREATE TABLE wb.batch_version(project_id text NOT NULL, batch_id text NOT NULL, version_id text NOT NULL, PRIMARY KEY(project_id,batch_id,version_id), FOREIGN KEY(project_id,batch_id) REFERENCES wb.release_batch, FOREIGN KEY(project_id,version_id) REFERENCES wb.system_version);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['requirement','batch_requirement','batch_version'] LOOP EXECUTE format('ALTER TABLE wb.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY read_scope ON wb.%I FOR SELECT USING(wb.allowed(project_id,false))',t); EXECUTE format('CREATE POLICY write_scope ON wb.%I FOR INSERT WITH CHECK(wb.allowed(project_id,true))',t); END LOOP; END $$;
-- Membership and source identities are append-only; correction requires a later
-- reviewed supersession/revocation migration, never destructive UPDATE/DELETE.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['requirement','batch_requirement','batch_version'] LOOP EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON wb.%I FOR EACH ROW EXECUTE FUNCTION wb.reject_history_change()',t); END LOOP; END $$;
DROP TRIGGER require_date_audit ON wb.release_batch;
CREATE CONSTRAINT TRIGGER require_date_audit AFTER UPDATE ON wb.release_batch DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(OLD.release_date IS DISTINCT FROM NEW.release_date OR OLD.revision IS DISTINCT FROM NEW.revision) EXECUTE FUNCTION wb.check_date_audit();
CREATE FUNCTION wb.date_relation_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.release_date IS DISTINCT FROM OLD.release_date THEN NEW.relation_revision=OLD.relation_revision+1; END IF; RETURN NEW; END $$;
CREATE TRIGGER date_relation_revision BEFORE UPDATE ON wb.release_batch FOR EACH ROW EXECUTE FUNCTION wb.date_relation_revision();
